from pathlib import Path
import re
root=Path(__file__).resolve().parents[1];out=root/'projects'
old=(out/'software.html').read_text(encoding='utf-8');header=re.search(r'<header class="portfolio-header">.*?</header>',old,re.S).group()
def page(title,desc,content,nav=True):
 navhtml=''
 if nav:
  navhtml='<nav class="project-navigation" aria-label="Software projects"><a href="software.html">All software</a><a href="software-omnisync.html">OmniSync</a><a href="software-side-notes.html">Side Notes</a><a href="software-px4.html">PX4 diagnostics</a><a href="software-sat-lab.html">SAT Lab</a><a href="software-vocabulary.html">Vocabulary</a></nav>'
 return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="{desc}"><title>{title} · Po Chun Tseng Engineering</title><link rel="stylesheet" href="../style.css?v=3"><link rel="stylesheet" href="../subpages.css?v=4"><link rel="stylesheet" href="../software.css?v=3"></head><body class="case-study software-study"><a class="skip" href="#main">Skip to content</a>{header}{navhtml}<main id="main" class="page">{content}</main><footer><strong>Po Chun Tseng / Engineering</strong><p>Software &amp; practical tools</p><a class="more" href="../index.html#work">← Selected work</a></footer></body></html>'''
def figure(file,alt,caption,cls=''):
 return f'<figure class="app-figure {cls}"><a href="../assets/software/{file}" aria-label="Open full-size image: {alt}"><img src="../assets/software/{file}" alt="{alt}" loading="lazy"></a><figcaption>{caption}</figcaption></figure>'
def flow(items):return '<ol class="app-flow" aria-label="Data flow">'+''.join(f'<li><span>{i+1:02}</span>{x}</li>' for i,x in enumerate(items))+'</ol>'
def section(k,title,body):return f'<section class="app-section"><div class="kicker">{k}</div><h2>{title}</h2>{body}</section>'
def card(title,text):return f'<article class="app-note"><h3>{title}</h3><p>{text}</p></article>'
def intro(k,title,lead,status,stack):
 return f'<a class="more" href="software.html">← All software</a><div class="kicker">{k}</div><h1>{title}</h1><p class="lead">{lead}</p><div class="app-meta"><span>{status}</span><span>Personal project</span><span>{stack}</span></div>'
def role(text,ai):return section('My contribution','What I built and verified',f'<p>{text}</p><p class="app-attribution">{ai}</p>')
content='''<a class="more" href="../index.html#work">← Selected work</a><div class="kicker">Applications · Browser tools · Engineering software</div><h1>Software &amp;<br>Practical Tools</h1><p class="lead">Apps I built for the way I work: keeping track of projects, taking notes while researching, and understanding what happened during a flight test.</p><div class="app-index-meta"><span>03 projects</span><span>Personal builds · 2026</span></div>
<section class="app-feature" aria-labelledby="omni-title"><div class="app-feature-copy"><span class="kicker">01 / Mobile web + desktop sync</span><h2 id="omni-title">OmniSync</h2><p class="app-pitch">Desktop project tasks.<br>Within reach on my phone.</p><p>Local Markdown checklists, cloud tasks, and calendar scheduling in one mobile dashboard.</p><div class="app-meta"><span>Actively used prototype</span><span>React · Node.js · Firestore</span></div><a class="app-button" href="software-omnisync.html">Explore OmniSync <span aria-hidden="true">↗</span></a></div><div class="phone-stage"><img src="../assets/software/screenshot-calendar.jpg" alt="OmniSync calendar on a phone, showing September 2026 and Projects, Calendar and Chat navigation"></div></section>
<div class="software-grid"><article class="software-card"><div class="card-stage notes-stage"><img src="../assets/software/side-notes-preview.png" alt="Side Notes interface rendered from its source with generic robot testing notes" loading="lazy"></div><div class="software-card-copy"><span class="kicker">02 / Chrome extension</span><h2>Side Notes</h2><p>A multi-note editor that stays beside the page I’m reading. Local storage, rich-text formatting, and no third-party packages.</p><span class="app-state">Locally installed prototype</span><a class="more" href="software-side-notes.html">Explore Side Notes ↗</a></div></article><article class="software-card"><div class="card-stage diagnostics-stage"><img src="../assets/software/main_diagnostic_dashboard.png" alt="PX4 diagnostics report with telemetry plots, correlation comparisons, and parameter checks" loading="lazy"></div><div class="software-card-copy"><span class="kicker">03 / Engineering tools</span><h2>PX4 Flight Diagnostics</h2><p>Python tools that turn flight logs into parameter checks, current-to-compass comparisons, and visual reports.</p><span class="app-state">Used on physical flight logs</span><a class="more" href="software-px4.html">Explore the diagnostics tools ↗</a></div></article></div>
<section class="app-section index-note"><div class="kicker">From everyday friction to working tools</div><h2>Different interfaces.<br>The same starting point.</h2><p>Each project began with a task I was already doing: checking desktop progress away from home, drafting alongside browser research, or digging through drone logs after a failed test. The pages follow the decisions and debugging behind each tool.</p></section>'''
(out/'software.html').write_text(page('Software & Practical Tools','Personal software projects: OmniSync, Side Notes, and PX4 flight diagnostics.',content,False),encoding='utf-8')
content=intro('Mobile web + desktop sync / June 2026–Present','OmniSync','A mobile dashboard connecting local engineering checklists, cloud tasks, and calendar scheduling.','Actively used prototype','React · Node.js · Firestore')
content+='<div class="app-summary"><div><h2>Project files at my desk.<br>Progress on my phone.</h2><p>Engineering tasks lived in local Markdown files, while coursework and deadlines lived in separate mobile apps. I wanted to check project progress away from the workstation without maintaining a second checklist.</p><p>OmniSync keeps desktop-synced tasks read-only on mobile and lets newly created cloud tasks sit alongside them.</p></div>'+figure('screenshot-calendar.jpg','OmniSync mobile calendar showing September 2026','Supplied mobile capture · Month calendar and bottom navigation.','phone-figure')+'</div>'
content+=section('01 / Main workflow','Check progress, then plan the next task',flow(['Edit a local Markdown checklist','A Node.js daemon parses the task items','Firestore stores the workspace summary','The mobile dashboard receives updates']))
content+='<div class="app-notes">'+card('Project workspaces','Completion summaries and collapsible task groups bring local checklist status into a phone-friendly view.')+card('Conversational scheduling','A client-side parser extracts task details, dates, and project names, with follow-up questions for missing information.')+card('Calendar views','Month and day views place scheduled tasks alongside the rest of the day’s commitments.')+'</div>'
content+=section('02 / Architecture','An outbound sync path from the workstation','<p>The desktop process reads configured project files and sends structured task summaries to Firestore. The mobile client listens for updates. This lets the phone read a cloud copy without connecting directly to the workstation.</p><div class="app-note"><h3>One-way local sync is a deliberate boundary</h3><p>Desktop-origin tasks are read-only in the mobile interface. Cloud-created tasks are editable, but the prototype does not write mobile changes back into local Markdown files.</p></div>')
content+=section('03 / Debugging','Resolve project names before creating tasks','<p>A chat request referring to “drone” could create a second project instead of attaching to the existing drone workspace. I added alias matching against existing workspaces and checked both cloud projects and synced workspaces before creating another card.</p><p>The reported check was to add a motor-test task using the nickname and confirm it appeared in the existing project. Similar project names remain an ambiguity the parser must resolve.</p>')
content+=section('04 / Boundary conditions','Keep an end-of-day deadline visible','<p>A deadline entered as <code>24:00</code> did not match a day-view grid indexed from 0 through 23. The prototype maps that input to <code>23:59</code> so it remains visible on the intended date. That display convention is a tradeoff, rather than an exact midnight representation.</p>'+figure('screenshot-chat.png','OmniSync chat with a natural-language physics-homework request','Supplied chat capture · Shows request entry; a completed scheduling response is not visible in this image.','phone-figure'))
content+=role('I defined the local-to-cloud data flow, built the sync daemon and React views, implemented project alias reconciliation and calendar handling, and tested the desktop-to-mobile workflow.','Built with AI pair-programming support for scaffolding, parser drafts, and debugging; my work included refining matching behavior and verifying boundary cases.')
content+=section('Current scope','A personal prototype with clear next steps','<div class="app-notes two">'+card('Implemented','Local checklist synchronization, cloud task creation, project grouping, calendar views, and a conversational scheduling parser.')+card('Still to build','Local-file writeback, push notifications, user authentication, and broader language understanding. The current parser uses client-side rules and a state machine, rather than a cloud LLM.')+'</div>')
(out/'software-omnisync.html').write_text(page('OmniSync','A local-to-cloud project dashboard with mobile tasks and calendar scheduling.',content),encoding='utf-8')
content=intro('Chrome extension / July 2026–Present','Side Notes','A multi-file note editor in Chrome’s native side panel, for writing alongside the page I’m reading.','Locally installed prototype','JavaScript · HTML · CSS · Manifest V3')
content+='<div class="app-summary"><div><h2>Keep the reference open.<br>Keep the notes beside it.</h2><p>Moving between a browser tab and a separate editor interrupted research and drafting. A single scratchpad also made it hard to separate subjects or projects.</p><p>Side Notes adds named notes, rich-text formatting, a live word count, and local persistence inside the browser’s docked panel.</p></div>'+figure('side-notes-preview.png','Side Notes source-rendered interface with generic bench-test notes','Interface rendered from the supplied HTML and CSS with sample content. This is a static preview, not a live extension session.','phone-figure')+'</div>'
content+=section('01 / User workflow','Create, format, and return to a note',flow(['Open the native side panel','Create or select a named note','Type and format the document','Resume the last active note later']))
content+='<div class="app-notes">'+card('Independent documents','A selector switches between stored notes, keeping different topics out of one long scratchpad.')+card('Rich-text editing','A contenteditable editor supports emphasis, lists, and text color through a compact toolbar.')+card('Local persistence','Edits are stored in chrome.storage.local after a 500 ms pause in typing. No cloud account is required.')+'</div>'
content+=section('02 / Platform choice','Use the browser’s panel instead of a page overlay','<p>I chose Chrome’s native Side Panel API so the editor lives in an extension context alongside the active page. It avoids relying on a floating widget injected into each website.</p><p>The supplied manifest requests <code>sidePanel</code> and <code>storage</code>. The interface uses plain JavaScript, HTML, and CSS, with no third-party runtime packages.</p>')
content+=section('03 / A rendering regression','Preserve the spacing in existing notes','<p>Moving from a textarea to a rich-text editor changed how spaces and line breaks rendered. Existing multiline notes could collapse into a continuous block.</p><p>I applied <code>white-space: pre-wrap</code> to the editor and checked older notes and indented text after switching documents. This addressed rendering without rewriting the stored text.</p><pre class="app-code"><code>#note-editor {\n  white-space: pre-wrap;\n}</code></pre>')
content+=section('04 / Persistence tradeoff','Update the interface immediately; save after a pause','<p>The word count updates on input, while storage writes use a 500 ms trailing debounce. This reduces repeated writes during typing. If the browser process is killed before the pending save runs, the last characters may not be persisted.</p>')
content+=role('I defined the note-management workflow and local storage schema, configured the extension manifest and panel behavior, diagnosed the spacing regression, and manually tested resizing, note switching, and persistence.','AI assistance supported initial scaffolding and event-handler drafts. I reviewed behavior and tested the integration in Chrome.')
content+=section('Current scope','A focused local utility','<div class="app-notes two">'+card('Implemented','Multiple named notes, rich-text formatting, local autosave, last-active-note restoration, and word count.')+card('Still to build','Export, cross-device synchronization, full-text search, and configurable keyboard shortcuts. The extension is locally distributed and is not listed in the Chrome Web Store.')+'</div>')
(out/'software-side-notes.html').write_text(page('Side Notes','A local-first, multi-file Chrome side-panel note editor.',content),encoding='utf-8')
content=intro('Python tools / June–September 2026','PX4 Flight Diagnostics','A toolkit for examining flight logs, checking vehicle configuration, and visualizing sensor behavior after drone tests.','Diagnostics used on physical logs','Python · PyULog · NumPy · Plotly')
content+='<p class="app-crosslink">Part of the drone project · <a href="../drone/flight.html">Flight testing and hardware context ↗</a></p>'
content+=section('01 / The problem','Turn a flight failure into something inspectable','<p>Unexpected instability left many possible causes: configuration, power delivery, sensor interference, or software timing. Reading isolated telemetry streams made comparisons difficult.</p><p>I built scripts to extract relevant ULog data, compare battery current with magnetic-field readings, and flag known configuration and logged health issues.</p>'+figure('main_diagnostic_dashboard.png','PX4 report combining magnetic-field telemetry, current-to-magnetometer correlations, and a parameter audit','Supplied diagnostic report · Telemetry, cross-log comparisons, and parameter checks. The report describes particular logs and checks, not a guarantee of flight readiness.'))
content+=section('02 / Processing pipeline','From a ULog file to a readable report',flow(['Read a recorded PX4 ULog','Extract and align telemetry streams','Run parameter and health-message checks','Generate terminal and chart reports']))
content+='<div class="app-notes">'+card('Configuration checks','Inspect recorded parameters and flag mismatches against the project’s expected configuration.')+card('Sensor comparisons','Align current and magnetometer samples, then compute per-axis correlation for investigation.')+card('Visual inspection','Generate static plots and interactive reports for comparing signals over time.')+'</div>'
content+=section('03 / Investigation','Compare compass behavior with motor current','<p>The analysis aligns current and magnetic-field samples before calculating their correlation. The result helps identify patterns worth investigating in wiring, compass placement, and estimator behavior.</p><p>I used comparisons across physical test logs to guide hardware and parameter changes. Correlation is supporting evidence; it does not establish a fault’s cause by itself.</p>')
content+=section('04 / Make recurring checks repeatable','Encode what the investigation uncovered','<p>The verification script checks recorded parameters, battery behavior, logged magnetic-interference messages, and stack warnings. The supplied output shows a failed audit with individual pass/fail results, making the configuration issues visible in one place.</p>'+figure('terminal_verification_output.png','Supplied terminal report showing parameter failures and a strong magnetic interference message','Supplied verification output for Log 112 · The overall audit fails and identifies items to investigate.'))
content+=section('05 / Related autonomy work','Separate command streaming from vision updates','<p>The companion-computer stack also includes an asynchronous command-sender task and a mission state machine. This structure separates recurring velocity commands from variable-latency vision updates.</p><p>The source brief reports simulation and bench verification. A complete outdoor autonomous pickup mission remains unvalidated.</p><a class="more" href="../drone/autonomy.html">Explore the autonomy work ↗</a>')
content+=role('I developed the log-analysis and verification tools, investigated recorded flight behavior, and worked on the asynchronous control and mission-state architecture. PX4, MAVSDK, PyMAVLink, and PyULog provide the underlying flight and log interfaces.','AI assistance supported report scaffolding and data-access syntax. I inspected the telemetry, interpreted the findings, and revised the checks.')
content+=section('Current scope','Useful diagnostics; further field validation ahead','<div class="app-notes two">'+card('Used today','Physical-log analysis, recorded-parameter checks, health-message inspection, and generated telemetry reports.')+card('Remaining work','Full outdoor mission validation, closed-loop grasp feedback, and further disturbance testing. These project-specific diagnostics complement inspection and testing.')+'</div><p class="app-links"><a href="https://github.com/alberttseng0525/drone-project" target="_blank" rel="noopener noreferrer">Project repository ↗</a><a href="../drone/index.html">Complete drone project ↗</a></p>')
(out/'software-px4.html').write_text(page('PX4 Flight Diagnostics','Python tools for PX4 flight-log inspection, parameter checks, and telemetry reporting.',content),encoding='utf-8')
print('Built software overview and three project pages.')
content=intro('Web application / September 2026','SAT Reading &amp; Writing Lab','Skill-based question sets, answer explanations, timed sessions, mistake review, and progress tracking.','Published web app','JavaScript · TypeScript · D1')
content=content.replace('<span>Personal project</span>','')
content+='<p class="app-links"><a class="app-button" href="https://sat-boundaries-practice.alberttseng0525.chatgpt.site" target="_blank" rel="noopener noreferrer">Open SAT Lab ↗</a></p><p class="hint">The hosted app may require ChatGPT sign-in.</p>'
content+=section('01 / Practice workflow','Choose a skill, answer, and revisit mistakes',flow(['Filter by domain, skill, and difficulty','Complete a practice or timed set','Check the stored answer explanation','Review mistakes and progress']))
content+='<div class="app-notes">'+card('Focused practice','Session setup filters questions by topic, difficulty, and history, including unanswered, incorrect, and bookmarked items.')+card('Feedback and review','Practice mode reveals the correct answer and rationale. A mistake notebook makes missed questions available for another attempt.')+card('Accuracy and pace','Progress views aggregate coverage, accuracy, and recorded response time by domain and skill.')+'</div>'
content+=section('02 / Application structure','Local backup and authenticated progress storage','<p>The browser renders question records and manages session state. Progress is saved locally, then synchronized through an authenticated API to a per-user JSON record in Cloudflare D1.</p>'+figure('sat-architecture.svg','Source-derived SAT Lab architecture showing bundled questions, browser state, local backup, authenticated API, and D1 storage','Explanatory architecture diagram derived from source. It is not a runtime screenshot or proof of cloud synchronization.'))
content+=section('03 / Technical decisions','Keep practice state inspectable','<div class="app-notes">'+card('Local fallback','The client retains a browser backup when remote data is unavailable. This is a progress fallback, rather than a full offline application cache.')+card('Question presentation','Some question records support formatted images alongside expandable text, while answer selection remains interactive.')+card('Question-level timing','Attempt records store elapsed time. Analytics exclude missing historical timings rather than counting them as zero-second answers.')+'</div>')
content+=section('Evidence and scope','Implementation documented; runtime checks remain','<p>The supplied source inspection counted 1,232 question records across four domains and ten skills. These are content inventory counts, rather than learner outcomes.</p><p>The brief documents published status and practice, review, timing, and persistence code. A complete authenticated practice session and production persistence were not verified in that inspection.</p><p>The app grew out of my own PDF-based practice workflow. A complete sample walkthrough and further runtime checks would help document the result; no score improvement or learner-growth metric is claimed.</p>')
content+=section('Further verification','Progress conflicts and timing behavior','<p>The current implementation stores whole progress snapshots, without per-attempt conflict merging. Account switching, concurrent-device saves, import validation, and time accumulated in background tabs are useful next checks.</p><p>Question passages and screenshots are omitted from this portfolio page until reproduction permissions and suitable sample media are established.</p>')
(out/'software-sat-lab.html').write_text(page('SAT Reading & Writing Lab','A web practice tool with skill-based question sets, explanations, timed sessions, and mistake review.',content),encoding='utf-8')
p=out/'software.html';s=p.read_text(encoding='utf-8').replace('03 projects','04 projects').replace('Personal builds · 2026','Apps &amp; engineering tools · 2026').replace('Apps I built for the way I work: keeping track of projects, taking notes while researching, and understanding what happened during a flight test.','Software for project planning, browser research, flight diagnostics, and focused practice.')
s=s.replace('</div>\n<section class="app-section index-note">','''<article class="software-card sat-card"><div class="card-stage"><img src="../assets/software/sat-architecture.svg" alt="Source-derived architecture of SAT Lab\'s browser, progress API, and storage" loading="lazy"></div><div class="software-card-copy"><span class="kicker">04 / Learning application</span><h2>SAT Reading &amp; Writing Lab</h2><p>Focused practice sets, answer explanations, timed sessions, and a mistake notebook. A published web app with source-documented progress tracking.</p><span class="app-state">Published · May require sign-in</span><a class="more" href="software-sat-lab.html">Explore SAT Lab ↗</a></div></article></div>\n<section class="app-section index-note">''')
s=s.replace('Each project began with a task I was already doing: checking desktop progress away from home, drafting alongside browser research, or digging through drone logs after a failed test. The pages follow the decisions and debugging behind each tool.','The collection brings together everyday productivity tools, engineering diagnostics, and structured learning. Each page explains the implementation, the available evidence, and what remains to be developed or verified.')
p.write_text(s,encoding='utf-8')
print('Added SAT Lab as a fourth project with evidence-scoped descriptions.')
# Highlight the current software page in its local navigation.
for p in out.glob('software-*.html'):
 s=p.read_text(encoding='utf-8')
 s=s.replace(f'<a href="{p.name}">',f'<a href="{p.name}" aria-current="page">')
 p.write_text(s,encoding='utf-8')
