# Consistent unnumbered problem openings, followed by numbered implementation sections.
def renumber_sections_after_problem(s):
 counter=0
 def number(m):
  nonlocal counter
  counter+=1
  return f'<div class="kicker">{counter:02} / {m.group(1)}</div>'
 return re.sub(r'<div class="kicker">\d{2} / ([^<]+)</div>',number,s)
