# Real browser captures and project-specific visual sections.
def append_to_section(s,title,extra):
 pattern=r'<section class="app-section">.*?</section>'
 found=False
 def insert(m):
  nonlocal found
  block=m.group()
  if '<h2>'+title+'</h2>' in block:
   found=True
   return block[:-10]+extra+'</section>'
  return block
 s=re.sub(pattern,insert,s,flags=re.S)
 assert found,title
 return s
